#!/usr/bin/env node
// Generates templates/{ru,en}/exercises.md (the five-column user-facing table
// that scripts/lib/exercises.mjs#parseExerciseTable reads) from
// knowledge/exercises.md (the full eleven-column reference table).
//
// Usage: node scripts/dev/build-exercise-tables.mjs
//
// Re-run this whenever knowledge/exercises.md changes. Running it twice in a
// row produces byte-identical output — there is no randomness or timestamp in
// the generated files.

import { readFileSync, writeFileSync } from 'node:fs';
import { parseKnowledgeTable } from '../lib/exercises.mjs';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = fileURLToPath(new URL('../../', import.meta.url));
const SOURCE = `${ROOT}knowledge/exercises.md`;
const OUT_RU = `${ROOT}templates/ru/exercises.md`;
const OUT_EN = `${ROOT}templates/en/exercises.md`;

function buildRows(knowledgeRows, lang) {
  return knowledgeRows.map((row) => {
    const canonical = lang === 'ru' ? row.exerciseRu : row.exerciseEn;
    const ownAliases = lang === 'ru' ? row.aliasesRu : row.aliasesEn;
    const otherName = lang === 'ru' ? row.exerciseEn : row.exerciseRu;
    const otherAliases = lang === 'ru' ? row.aliasesEn : row.aliasesRu;

    const aliases = [...ownAliases, otherName, ...otherAliases];
    const muscles = [row.primaryMuscle, ...row.secondaryMuscles];

    return {
      exercise: canonical,
      aliases: aliases.join('; '),
      equipment: row.equipment.join('; '),
      muscles: muscles.join('; '),
      main: row.main ? 'yes' : 'no',
    };
  });
}

function renderTable(rows) {
  const header = '| Exercise | Aliases | Equipment | Muscles | Main |';
  const separator = '|---|---|---|---|---|';
  const body = rows.map(
    (r) => `| ${r.exercise} | ${r.aliases} | ${r.equipment} | ${r.muscles} | ${r.main} |`,
  );
  return [header, separator, ...body].join('\n') + '\n';
}

function main() {
  const knowledgeText = readFileSync(SOURCE, 'utf8');
  const knowledgeRows = parseKnowledgeTable(knowledgeText, SOURCE);

  if (knowledgeRows.length === 0) {
    throw new Error(`No exercise rows parsed from ${SOURCE} — check the section 6/7 headings.`);
  }

  const ruRows = buildRows(knowledgeRows, 'ru');
  const enRows = buildRows(knowledgeRows, 'en');

  const ruHeader = `<!-- Generated by scripts/dev/build-exercise-tables.mjs from knowledge/exercises.md. Do not edit by hand. -->\n\n# Упражнения\n\n`;
  const enHeader = `<!-- Generated by scripts/dev/build-exercise-tables.mjs from knowledge/exercises.md. Do not edit by hand. -->\n\n# Exercises\n\n`;

  writeFileSync(OUT_RU, ruHeader + renderTable(ruRows));
  writeFileSync(OUT_EN, enHeader + renderTable(enRows));

  console.log(`Parsed ${knowledgeRows.length} exercises from ${SOURCE}`);
  console.log(`Wrote ${ruRows.length} rows to ${OUT_RU}`);
  console.log(`Wrote ${enRows.length} rows to ${OUT_EN}`);
}

// Guarded so a test can `import { parseKnowledgeTable }` without triggering
// a real run against the checked-in knowledge/template files as a side effect.
// pathToFileURL, not `file://${argv[1]}`: on Windows argv[1] is a native
// path and the two never compare equal, so the script silently did nothing.
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main();
}
